import{_ as a,C as s,c as n,o,a3 as e,G as d}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/workflows/index.md","filePath":"master/supply-chain/manufacturing/workflows/index.md","lastUpdated":1793074831000}'),i={name:"master/supply-chain/manufacturing/workflows/index.md"};function l(h,t,g,c,u,p){const r=s("ImagePopup");return o(),n("div",null,[t[0]||(t[0]=e(`<h1 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h1><p>A manufacturing order moves through a fixed lifecycle. Each state tells you what has happened and which buttons you can use next. This page is the map. The pages linked below explain each step in depth.</p><blockquote><p><strong>In simple words:</strong> An order starts as a draft, gets confirmed, is worked on, and ends as done.</p></blockquote><p>Open <code>Manufacturing → Operations → Manufacturing Orders</code>.</p><h2 id="the-lifecycle" tabindex="-1">The lifecycle <a class="header-anchor" href="#the-lifecycle" aria-label="Permalink to &quot;The lifecycle&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Draft ─► Confirmed ─► In Progress ─► To Close ─► Done</span></span>
<span class="line"><span>  │          │              │            │</span></span>
<span class="line"><span>  └──────────┴──────────────┴────────────┴──► Cancelled</span></span></code></pre></div><p>The order header shows a stepper with <strong>Draft</strong>, <strong>Confirmed</strong> and <strong>Done</strong>. <strong>In Progress</strong>, <strong>To Close</strong> and <strong>Cancelled</strong> appear only while they are the current state.</p>`,7)),d(r,{src:"/images1/manufacturing/mo_state_stepper.png",alt:"MO/2 view header showing the state stepper Draft, Confirmed, Done with Confirmed highlighted, and the header buttons"}),t[1]||(t[1]=e('<h2 id="states" tabindex="-1">States <a class="header-anchor" href="#states" aria-label="Permalink to &quot;States&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Draft</strong></td><td>The order is saved. Nothing is reserved yet.</td></tr><tr><td><strong>Confirmed</strong></td><td>The order is accepted and its transfers exist.</td></tr><tr><td><strong>In Progress</strong></td><td>Work has started.</td></tr><tr><td><strong>To Close</strong></td><td>Work is finished and the order waits to be closed.</td></tr><tr><td><strong>Done</strong></td><td>Components are consumed and the finished product exists.</td></tr><tr><td><strong>Cancelled</strong></td><td>The order is stopped.</td></tr></tbody></table><h2 id="readiness" tabindex="-1">Readiness <a class="header-anchor" href="#readiness" aria-label="Permalink to &quot;Readiness&quot;">​</a></h2><p>The <strong>MO Readiness</strong> column tells you if a confirmed order can start.</p><table tabindex="0"><thead><tr><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Waiting</strong></td><td>Components are not all available.</td></tr><tr><td><strong>Ready</strong></td><td>The order can start.</td></tr><tr><td><strong>Waiting another operation</strong></td><td>A step must finish before this one can start.</td></tr></tbody></table><h2 id="buttons-by-state" tabindex="-1">Buttons by state <a class="header-anchor" href="#buttons-by-state" aria-label="Permalink to &quot;Buttons by state&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Buttons</th></tr></thead><tbody><tr><td><strong>Draft</strong></td><td><strong>Confirm</strong></td></tr><tr><td><strong>Confirmed</strong></td><td><strong>Produce All</strong>, <strong>Plan</strong>, <strong>Start</strong>, <strong>Cancel</strong>, <strong>Print</strong></td></tr><tr><td><strong>Confirmed and planned</strong></td><td><strong>Unplan</strong> is added</td></tr><tr><td><strong>In Progress</strong></td><td><strong>Produce All</strong> or <strong>Produce</strong>, <strong>Cancel</strong>, <strong>Print</strong></td></tr><tr><td><strong>To Close</strong></td><td><strong>Produce All</strong> or <strong>Produce</strong>, <strong>Cancel</strong>, <strong>Print</strong></td></tr><tr><td><strong>Done</strong></td><td>No action buttons</td></tr><tr><td><strong>Cancelled</strong></td><td>No action buttons</td></tr></tbody></table><p><strong>Produce</strong> replaces <strong>Produce All</strong> when <strong>Quantity Producing</strong> differs from the order quantity.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Page</th></tr></thead><tbody><tr><td>Create, confirm, start, cancel and print</td><td><a href="./manufacturing-orders.html">Manufacturing orders</a></td></tr><tr><td>Schedule work orders on work centers</td><td><a href="./plan-and-schedule.html">Plan and schedule</a></td></tr><tr><td>Run, pause and finish each step</td><td><a href="./work-orders.html">Work orders</a></td></tr><tr><td>Consume components and make the product</td><td><a href="./produce-and-consume.html">Produce and consume</a></td></tr><tr><td>Track lots and serial numbers</td><td><a href="./lots-and-serial-numbers.html">Lots and serial numbers</a></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The warehouse step setting decides which transfers appear. See <a href="./../basic-setup/one-step-manufacturing.html">One-step</a>, <a href="./../basic-setup/two-step-manufacturing.html">two-step</a> and <a href="./../basic-setup/three-step-manufacturing.html">three-step</a> manufacturing.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../basic-setup/manufacturing-order-costs.html">Manufacturing order costs</a></li><li><a href="./../basic-setup/">Basic setup</a></li><li><a href="./../get-started/manufacturing-settings.html">Manufacturing settings</a></li></ul>',13))])}const b=a(i,[["render",l]]);export{m as __pageData,b as default};
